CREATE TYPE public.portfolio_theme AS ENUM ('moderno','quente','minimal');
CREATE TYPE public.portfolio_input_method AS ENUM ('pdf_upload','linkedin_text','guided_questions');
CREATE TABLE public.profiles(id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE,email text NOT NULL DEFAULT '',full_name text NOT NULL DEFAULT '',avatar_url text,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),CHECK(length(full_name)<=120),CHECK(length(email)<=254));
GRANT SELECT,INSERT,UPDATE,DELETE ON public.profiles TO authenticated;
GRANT ALL ON public.profiles TO service_role;
ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
CREATE POLICY profiles_owner ON public.profiles FOR ALL TO authenticated USING(id=auth.uid()) WITH CHECK(id=auth.uid());
CREATE FUNCTION public.create_pitchfolio_profile() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.profiles(id,email,full_name) VALUES(NEW.id,COALESCE(NEW.email,''),left(COALESCE(NEW.raw_user_meta_data->>'full_name',''),120)) ON CONFLICT(id) DO NOTHING; RETURN NEW; END; $$;
CREATE TRIGGER pitchfolio_profile_signup AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.create_pitchfolio_profile();
INSERT INTO public.profiles(id,email,full_name) SELECT id,COALESCE(email,''),left(COALESCE(raw_user_meta_data->>'full_name',''),120) FROM auth.users ON CONFLICT(id) DO NOTHING;
ALTER TABLE public.portfolios ADD COLUMN is_published boolean NOT NULL DEFAULT false, ADD COLUMN selected_theme public.portfolio_theme NOT NULL DEFAULT 'moderno',ADD COLUMN name text NOT NULL DEFAULT '',ADD COLUMN about_me text NOT NULL DEFAULT '',ADD COLUMN experience jsonb NOT NULL DEFAULT '[]'::jsonb,ADD COLUMN photo_url text,ADD COLUMN input_method public.portfolio_input_method NOT NULL DEFAULT 'guided_questions';
UPDATE public.portfolios SET is_published=true,selected_theme=CASE WHEN theme IN ('moderno','quente','minimal') THEN theme::public.portfolio_theme ELSE 'moderno'::public.portfolio_theme END,name=COALESCE(data->>'name',''),about_me=COALESCE(data->>'bio','');
ALTER TABLE public.portfolios ADD CONSTRAINT portfolios_profile_fk FOREIGN KEY(user_id) REFERENCES public.profiles(id) ON DELETE CASCADE;
COMMENT ON COLUMN public.portfolios.theme IS 'DEPRECATED: selected_theme is authoritative; mirrored for existing clients';
GRANT SELECT ON public.portfolios TO anon;
GRANT SELECT,INSERT,UPDATE,DELETE ON public.portfolios TO authenticated;
GRANT ALL ON public.portfolios TO service_role;
DROP POLICY "Public can view portfolios" ON public.portfolios;
CREATE POLICY portfolios_public ON public.portfolios FOR SELECT TO anon,authenticated USING(is_published);
CREATE POLICY portfolios_owner_read ON public.portfolios FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE TABLE public.pitch_decks(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),portfolio_id uuid NOT NULL UNIQUE REFERENCES public.portfolios(id) ON DELETE CASCADE,user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE,slide_1_who_i_am jsonb NOT NULL,slide_2_what_i_did jsonb NOT NULL,slide_3_skills jsonb NOT NULL,slide_4_highlight jsonb NOT NULL,slide_5_contact jsonb NOT NULL,pdf_export_url text,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.pitch_decks TO anon;
GRANT SELECT,INSERT,UPDATE,DELETE ON public.pitch_decks TO authenticated;
GRANT ALL ON public.pitch_decks TO service_role;
ALTER TABLE public.pitch_decks ENABLE ROW LEVEL SECURITY;
CREATE POLICY decks_public ON public.pitch_decks FOR SELECT TO anon,authenticated USING(EXISTS(SELECT 1 FROM public.portfolios p WHERE p.id=portfolio_id AND p.is_published));
CREATE POLICY decks_owner ON public.pitch_decks FOR ALL TO authenticated USING(user_id=auth.uid()) WITH CHECK(user_id=auth.uid() AND EXISTS(SELECT 1 FROM public.portfolios p WHERE p.id=portfolio_id AND p.user_id=auth.uid()));
CREATE TABLE public.usage_windows(scope text NOT NULL,window_start timestamptz NOT NULL,used integer NOT NULL DEFAULT 0,PRIMARY KEY(scope,window_start));
GRANT ALL ON public.usage_windows TO service_role;
ALTER TABLE public.usage_windows ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION public.consume_pitchfolio_budget(p_kind text) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE scope_key text; budget integer; consumed integer; BEGIN
 IF p_kind NOT IN ('ai','upload') THEN RAISE EXCEPTION 'Invalid budget'; END IF;
 IF p_kind='upload' AND auth.uid() IS NULL THEN RAISE EXCEPTION 'Authentication required'; END IF;
 scope_key=p_kind||':'||COALESCE(auth.uid()::text,'anonymous-global');
 budget=CASE WHEN p_kind='ai' AND auth.uid() IS NULL THEN 60 ELSE 20 END;
 INSERT INTO public.usage_windows(scope,window_start,used) VALUES(scope_key,date_trunc('hour',now()),1) ON CONFLICT(scope,window_start) DO UPDATE SET used=usage_windows.used+1 WHERE usage_windows.used<budget RETURNING used INTO consumed;
 RETURN consumed IS NOT NULL; END; $$;
REVOKE ALL ON FUNCTION public.consume_pitchfolio_budget(text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.consume_pitchfolio_budget(text) TO anon,authenticated;
CREATE POLICY pitchfolio_storage_read ON storage.objects FOR SELECT TO authenticated USING(bucket_id IN ('resumes','avatars','published_pdfs') AND (storage.foldername(name))[1]=auth.uid()::text);
CREATE POLICY pitchfolio_storage_insert ON storage.objects FOR INSERT TO authenticated WITH CHECK(bucket_id IN ('resumes','avatars','published_pdfs') AND (storage.foldername(name))[1]=auth.uid()::text AND public.consume_pitchfolio_budget('upload'));
CREATE POLICY pitchfolio_storage_update ON storage.objects FOR UPDATE TO authenticated USING(bucket_id IN ('resumes','avatars','published_pdfs') AND (storage.foldername(name))[1]=auth.uid()::text) WITH CHECK(bucket_id IN ('resumes','avatars','published_pdfs') AND (storage.foldername(name))[1]=auth.uid()::text AND public.consume_pitchfolio_budget('upload'));
CREATE POLICY pitchfolio_storage_delete ON storage.objects FOR DELETE TO authenticated USING(bucket_id IN ('resumes','avatars','published_pdfs') AND (storage.foldername(name))[1]=auth.uid()::text);
CREATE INDEX portfolios_user_id_idx ON public.portfolios(user_id);
CREATE INDEX pitch_decks_user_id_idx ON public.pitch_decks(user_id);